META = {
    "name": "banking_words_in_prefix",
    "intent": "fires at a token position when the 500 characters immediately before it contain one of a fixed list of banking, investment or money words (bank, bonds, investment, shareholders, pension, credits, lending, deposited, debited, subsidiary, money, dollar, price, cost, cash, trade, sales, purchases, funds, financial, capital, wealth)",
    "kind": "absolute",
    "upstream": [],
}

TERM = re.compile(
    r"\b(bank|banks|banking|bonds|investment|investments|invested|"
    r"shareholder|shareholders|pension|credits|credited|debited|"
    r"deposited|lending|subsidiary|subsidiaries|"
    r"money|moneys|dollar|dollars|price|prices|cost|costs|cash|"
    r"trade|sales|purchases|fund|funds|financial|capital|wealth)\b",
    re.I,
)


def fires(w):
    return bool(TERM.search(w.left[-500:]))

META = {
    "name": "url_span_in_prefix",
    "intent": "fires at a token position when the 500 characters immediately before it contain a web address (http://, https:// or www.)",
    "kind": "absolute",
    "upstream": [],
}

URL = re.compile(r"https?://|www\.", re.I)


def fires(w):
    return bool(URL.search(w.left[-500:]))

META = {
    "name": "bare_slash_or_dot_fragment",
    "intent": "fires when the current token is itself a bare '/' or a dot-prefixed 2-6 letter fragment, i.e. a punctuation/fragment token rather than a word (a token-shape rule)",
    "kind": "absolute",
    "upstream": [],
}

SHAPE = re.compile(r"^(?:/|\.[a-z]{2,6})$", re.I)


def fires(w):
    return bool(SHAPE.match(w.tok.strip()))

META = {
    "name": "provision_verb_in_prefix",
    "intent": "fires at a token position when the 30 characters immediately before it contain one of the verb forms laid, lack, lacks, lacked, provide, provides or provided",
    "kind": "absolute",
    "upstream": [],
}

VERB = re.compile(r"\b(laid|lack|lacks|lacked|provide|provides|provided)\b", re.I)


def fires(w):
    return bool(VERB.search(w.left[-30:]))

META = {
    "name": "complement_head_token",
    "intent": "fires when the current token is one of four fixed complement-head words (prerequisites, necessary, underlying, theory); a token-identity rule",
    "kind": "absolute",
    "upstream": [],
}

WORDS = ("prerequisites", "necessary", "underlying", "theory")


def fires(w):
    return w.tok.strip() in WORDS

META = {
    "name": "abstract_suffix_token",
    "intent": "fires when the tested token is a single alphabetic word ending in one of a fixed class of Latinate abstract-noun or adjective suffixes (-ary, -ory, -ing, -ites, -sis, -ity, -ism, -ance, -ence); a morphological token-shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

SUFFIX = re.compile(r"(ary|ory|ing|ites|sis|ity|ism|ance|ence)$", re.I)
WORD = re.compile(r"^[A-Za-z]+$")


def fires(w):
    t = w.tok.strip()
    return bool(WORD.match(t)) and bool(SUFFIX.search(t))

META = {
    "name": "determiner_boundary_token",
    "intent": "fires when the tested token sits at the determiner boundary of a noun phrase: it is either the bare determiner 'the' itself, or the single alphabetic word immediately following that determiner; a positional token-role rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

ALPHA = re.compile(r"^[A-Za-z]+$")


def fires(w):
    t = w.tok.strip()
    p = w.prev(1).strip()
    return t == "the" or (p == "the" and bool(ALPHA.match(t)))

META = {
    "name": "single_upper_letter_token",
    "intent": "fires when the tested token is a single uppercase Latin letter, optionally preceded by a hyphen; a token-shape rule for initial and abbreviation tokens, not a word list",
    "kind": "absolute",
    "upstream": [],
}

SHAPE = re.compile(r"^-?[A-Z]$")


def fires(w):
    return bool(SHAPE.match(w.tok.strip()))

META = {
    "name": "compound_boundary_token",
    "intent": "fires when the tested token opens the second element of a hyphenated compound: either the token itself begins with a hyphen, or the immediately preceding token ends with a hyphen or an en-dash; a punctuation-role context rule",
    "kind": "absolute",
    "upstream": [],
}


def fires(w):
    t = w.tok.strip()
    p = w.prev(1).strip()
    return t.startswith("-") or p.endswith("-") or p.endswith("\u00e2\u0122\u0135")

META = {
    "name": "proper_name_prefix_context",
    "intent": "fires when the token immediately before the tested one is a proper-name or list-boundary fragment: it begins with an uppercase letter, is a '#' or '*' list marker, or ends with a hyphen or an en-dash; a prefix-role context rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

DASH = "\u00e2\u0122\u0135"


def fires(w):
    p = w.prev(1).strip()
    if not p:
        return False
    return (p[0].isupper() or p in ("#", "*") or p.endswith("-")
            or p.endswith(DASH))

META = {
    "name": "comma_in_prefix",
    "intent": "fires when a comma appears in the 80 characters immediately before the tested token, i.e. the token sits after a comma-delimited phrase; a punctuation-context rule",
    "kind": "absolute",
    "upstream": [],
}


def fires(w):
    return "," in w.left[-80:]

META = {
    "name": "capitalised_word_in_prefix",
    "intent": "fires when a capitalised word (an uppercase letter followed by a lowercase letter) appears in the 40 characters immediately before the tested token; a proper-name or sentence-initial context rule",
    "kind": "absolute",
    "upstream": [],
}

CAP = re.compile(r"\b[A-Z][a-z]")


def fires(w):
    return bool(CAP.search(w.left[-40:]))

META = {
    "name": "compact_fragment_token",
    "intent": "fires when the tested token is a compact non-prose fragment: it either has no leading space (a word-internal sub-word continuation) or the 80 characters immediately before it contain a '*' or '#' list bullet; a token-context rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}


def fires(w):
    if not w.tok.startswith(" "):
        return True
    return "*" in w.left[-80:] or "#" in w.left[-80:]

META = {
    "name": "consonant_vowel_juncture",
    "intent": "fires when the previous token ends in a consonant and the tested token begins with a vowel, i.e. a sub-word split at a consonant-vowel syllable onset; an orthographic token-juncture rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

CONSONANT_END = re.compile(r"[bcdfghjklmnpqrstvwxz]$", re.I)
VOWEL_START = re.compile(r"^[aeiou]", re.I)


def fires(w):
    return (bool(CONSONANT_END.search(w.prev(1).strip()))
            and bool(VOWEL_START.match(w.tok.strip())))

META = {
    "name": "modifier_head_shape",
    "intent": "fires when the tested token is an alphabetic word of at least 3 letters and the token immediately before it is an alphabetic word of at least 4 letters, i.e. a long attributive modifier directly followed by a content head; a token-shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

HEAD = re.compile(r"^[A-Za-z]{3,}$")
MODIFIER = re.compile(r"^[A-Za-z]{4,}$")


def fires(w):
    return bool(HEAD.match(w.tok.strip())) and bool(MODIFIER.match(w.prev(1).strip()))

META = {
    "name": "comma_clause_content_head",
    "intent": "fires when the tested token is an alphabetic word of at least 3 letters and the 60 characters immediately before it contain a comma, i.e. a content head opening the phrase after a comma-delimited clause; a narrowed punctuation-context rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

HEAD = re.compile(r"^[A-Za-z]{3,}$")


def fires(w):
    return bool(HEAD.match(w.tok.strip())) and "," in w.left[-60:]

META = {
    "name": "latinate_suffix_token",
    "intent": "fires when the tested token ends in one of a fixed class of Latin and Greek-derived adjectival or nominal suffixes (-ial, -ian, -ine, -eum, -alis, -arius, -ensis, -inus, -ina, -icum, -orum, -ibus, -tud, -ctio, -us, -um, -is, -ae, -ando, -endo); a morphological token-shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

SUFFIX = re.compile(
    r"(ial|ian|ine|eum|alis|arius|ensis|inus|ina|icum|orum|ibus|tud|ctio|us|um|is|ae|ando|endo)\b",
    re.I,
)


def fires(w):
    return bool(SUFFIX.search(w.tok.strip()))

META = {
    "name": "capitalised_prefix_content_head",
    "intent": "fires when the tested token is an alphabetic word of at least 3 letters and a capitalised word (uppercase letter followed by a lowercase letter) appears in the 40 characters immediately before it, i.e. a content head in a sentence-initial or proper-name context; a narrowed context rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

HEAD = re.compile(r"^[A-Za-z]{3,}$")
CAP = re.compile(r"\b[A-Z][a-z]")


def fires(w):
    return bool(HEAD.match(w.tok.strip())) and bool(CAP.search(w.left[-40:]))

META = {
    "name": "derivational_suffix_token",
    "intent": "fires when the tested token ends in one of the productive English derivational suffixes (-ic, -al, -ed, -ing, -ly, -ion, -ity, -ous, -ive, -ism, -ist, -ate, -ise, -ize), i.e. a morphologically derived adjective or noun ending including word-internal suffix fragments; a closed morphological token-shape class, not a word list copied from a unit's rows",
    "kind": "absolute",
    "upstream": [],
}

SUFFIX = re.compile(
    r"(ic|al|ed|ing|ly|ion|ity|ous|ive|ism|ist|ate|ise|ize)$", re.I
)


def fires(w):
    return bool(SUFFIX.search(w.tok.strip()))

META = {
    "name": "long_preceding_content_word",
    "intent": "fires when the token immediately before the tested one is an alphabetic word of at least four letters, i.e. the tested token is a continuation inside a run of long prose words rather than after a number, a bracket or a list marker; a preceding-token shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

WORD = re.compile(r"^[A-Za-z]{4,}$")


def fires(w):
    return bool(WORD.match(w.prev(1).strip()))

META = {
    "name": "word_internal_fragment",
    "intent": "fires when the tested token has no leading space, i.e. it is the continuation of a word that the tokenizer split rather than a fresh space-delimited word; a token-position shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}


def fires(w):
    return not w.tok.startswith(" ")

META = {
    "name": "nonascii_byte_in_prefix",
    "intent": "fires when the 80 characters immediately before the tested token contain at least one non-ASCII character (an accented letter, a typographic dash or a mojibake byte), i.e. the token sits in a passage with internationally encoded typography rather than plain ASCII prose; a prefix character-class rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}


def fires(w):
    return any(ord(ch) > 127 for ch in w.left[-80:])

META = {
    "name": "closed_function_word_token",
    "intent": "fires when the tested token is one of the closed grammatical function words (articles, prepositions, conjunctions, auxiliaries and the common wh-/degree adverbs), i.e. a grammatical glue token rather than a content word; a closed grammatical class, not a word list copied from a unit's rows",
    "kind": "absolute",
    "upstream": [],
}

FUNC = re.compile(
    r"^(?:to|of|in|at|by|with|from|up|on|is|the|a|an|and|or|for|as|into|"
    r"that|this|it|be|are|was|were|has|had|not|but|its|their|which|such|"
    r"also|can|may|these|those|have|been|more|most|other|some|all|any|"
    r"each|both|no|per|via|than|then|so|if|when|where|who|how)$", re.I
)


def fires(w):
    return bool(FUNC.match(w.tok.strip()))

META = {
    "name": "coordinated_phrase_head",
    "intent": "fires when the tested token is a short alphabetic word of at most four letters and the token immediately before it ends in the closed coordinating conjunction class 'and' or 'or', i.e. the first word of the second conjunct in a coordinated phrase; a positional role rule over a closed grammatical class, not a word list",
    "kind": "absolute",
    "upstream": [],
}

SHORT = re.compile(r"^[A-Za-z]{1,4}$")
CONJUNCTION = re.compile(r"(?:^|\s)(?:and|or)$", re.I)


def fires(w):
    return bool(SHORT.match(w.tok.strip())) and bool(CONJUNCTION.search(w.prev(1)))

META = {
    "name": "unicode_alpha_fragment_capitalised_prefix",
    "intent": "fires when the tested token is a word-internal continuation with no leading space made of at least three Unicode letters (so accented and mojibake name fragments count) and a capitalised word appears in the 40 characters immediately before it; a token-shape plus prefix-context rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

ALPHA = re.compile(r"^[^\W\d_]{3,}$", re.UNICODE)
CAPITALISED = re.compile(r"\b[A-Z][a-z]")


def fires(w):
    return (not w.tok.startswith(" ")
            and bool(ALPHA.match(w.tok.strip()))
            and bool(CAPITALISED.search(w.left[-40:])))

META = {
    "name": "space_delimited_short_consonant_word",
    "intent": "fires when the tested token is a fresh space-delimited word (it has a leading space) of two to four letters that begins with a consonant, i.e. a short grammatical word opening a new word rather than a word-internal continuation; a token-position and token-shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

SHORT = re.compile(r"^[A-Za-z]{2,4}$")
CONSONANT = re.compile(r"^[bcdfghjklmnpqrstvwxz]", re.I)


def fires(w):
    return (w.tok.startswith(" ")
            and bool(SHORT.match(w.tok.strip()))
            and bool(CONSONANT.match(w.tok.strip())))

META = {
    "name": "line_initial_after_newline",
    "intent": "fires when the 30 characters immediately before the tested token contain a line break, i.e. the token opens a fresh line such as a list item or a section heading; a positional line-start role, not a word list",
    "kind": "absolute",
    "upstream": [],
}


def fires(w):
    return "\n" in w.left[-30:]

META = {
    "name": "spaced_long_content_word",
    "intent": "fires when the tested token is a space-delimited run of at least six ASCII letters, i.e. a full long word rather than a one- or two-letter fragment; a token-length shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

LONG = re.compile(r"^[A-Za-z]{6,}$")


def fires(w):
    return w.tok.startswith(" ") and bool(LONG.match(w.tok.strip()))

META = {
    "name": "vowel_initial_short_word",
    "intent": "fires when the tested token is a fresh space-delimited word of two to four letters that begins with a vowel, i.e. a short vowel-initial grammatical or function word opening a new word rather than a word-internal continuation; a token-shape rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

VOWEL_SHORT = re.compile(r"^[aeiou][a-z]{1,3}$", re.I)


def fires(w):
    return (w.tok.startswith(" ")
            and bool(VOWEL_SHORT.match(w.tok.strip())))

META = {
    "name": "digit_in_prev_token",
    "intent": "fires when the token immediately before the tested one contains a decimal digit, i.e. a token that follows a numeral or a year-like numeric string; a positional numeric-context rule, not a word list",
    "kind": "absolute",
    "upstream": [],
}

DIGIT = re.compile(r"[0-9]")


def fires(w):
    return bool(DIGIT.search(w.prev(1)))

META = {
    "name": "pure_punctuation_token",
    "intent": "fires when the tested token is a punctuation-only token: after stripping surrounding whitespace it is non-empty and contains no ASCII letter or digit; a generalisable token-shape class, not a word list",
    "kind": "absolute",
    "upstream": [],
}

ALNUM = re.compile(r"[A-Za-z0-9]")


def fires(w):
    t = w.tok.strip()
    return bool(t) and not ALNUM.search(w.tok)

META = {
    "name": "circuit_l0u465_on_l16u61_off",
    "intent": "fires where upstream unit L0 u465 is in its high state and upstream unit L16 u61 is not; the L16 state vetoes the positions that also carry L0 u465 high, keeping only the gated subset",
    "kind": "relative",
    "upstream": [[0, 465], [16, 61]],
}


def fires(w):
    return w.up(0, 465) and not w.up(16, 61)

META = {
    "name": "circuit_l1u886_on_l4u2437_off",
    "intent": "fires where upstream unit L1 u886 is in its high state and upstream unit L4 u2437 is not; the L4 state vetoes the low-pole positions that also carry L1 u886 high, keeping only the gated subset",
    "kind": "relative",
    "upstream": [[1, 886], [4, 2437]],
}


def fires(w):
    return w.up(1, 886) and not w.up(4, 2437)

META = {
    "name": "circuit_l8u87_on_l4u1335_off",
    "intent": "fires where upstream unit L8 u87 is in its high state and upstream unit L4 u1335 is not; the L4 state vetoes the low-pole positions that also carry L8 u87 high, keeping only the gated subset",
    "kind": "relative",
    "upstream": [[8, 87], [4, 1335]],
}


def fires(w):
    return w.up(8, 87) and not w.up(4, 1335)

META = {
    "name": "bare_capital_letter_token",
    "intent": "fires when the tested token is exactly one bare uppercase ASCII letter with no leading space and no punctuation prefix; a token-shape rule, not a word list, that keeps the unmarked single-letter shape (e.g. MA«O») but excludes hyphen- or slash-prefixed letters (e.g. «-O», «/T»)",
    "kind": "absolute",
    "upstream": [],
}

SHAPE = re.compile(r"^[A-Z]$")


def fires(w):
    return bool(SHAPE.match(w.tok))

META = {
    "name": "punctuation_leading_letter_token",
    "intent": "fires when the tested token begins with a non-alphanumeric, non-space punctuation character immediately followed by a letter; a token-shape rule, not a word list, for slash-, hyphen-, comma- or parenthesis-attached letter fragments such as «/T» or «-N»",
    "kind": "absolute",
    "upstream": [],
}

SHAPE = re.compile(r"^[^A-Za-z0-9\s][A-Za-z]")


def fires(w):
    return bool(SHAPE.match(w.tok))

META = {
    "name": "z_gate_l0u465_on_l16u61_off",
    "intent": "fires where upstream unit L0 u465 is in its high state and upstream unit L16 u61 is not; the L16 state vetoes the positions that also carry L0 u465 high, keeping only the gated subset",
    "kind": "relative",
    "upstream": [[0, 465], [16, 61]],
}


def fires(w):
    return w.up(0, 465) and not w.up(16, 61)

META = {
    "name": "z_gate_l1u886_on_l4u2437_off",
    "intent": "fires where upstream unit L1 u886 is in its high state and upstream unit L4 u2437 is not; the L4 state vetoes the low-pole positions that also carry L1 u886 high, keeping only the gated subset",
    "kind": "relative",
    "upstream": [[1, 886], [4, 2437]],
}


def fires(w):
    return w.up(1, 886) and not w.up(4, 2437)

META = {
    "name": "z_gate_l8u87_on_l4u1335_off",
    "intent": "fires where upstream unit L8 u87 is in its high state and upstream unit L4 u1335 is not; the L4 state vetoes the low-pole positions that also carry L8 u87 high, keeping only the gated subset",
    "kind": "relative",
    "upstream": [[8, 87], [4, 1335]],
}


def fires(w):
    return w.up(8, 87) and not w.up(4, 1335)

META = {
    "name": "veto_l14u293_high_l0u2296_off",
    "intent": "fires where upstream unit L14 u293 is in its high state and upstream unit L0 u2296 is not; upstream L0 u2296 is high on the weakest rows, so its high state genuinely excludes those positions while L14 u293 stays high on the strongest ones",
    "kind": "relative",
    "upstream": [[14, 293], [0, 2296]],
}


def fires(w):
    return w.up(14, 293) and not w.up(0, 2296)
